effect.shader:
// S_GlowAura implementation for Alight Motion

#define PI 3.14159265359

float getLuma(vec3 rgb) {
    return dot(rgb, vec3(0.2126, 0.7152, 0.0722));
}

vec3 auraPalette(float t) {
    // Base cycling colors
    vec3 col = 0.5 + 0.5 * cos(6.28318 * (t + vec3(0.0, 0.33, 0.67)));

    // Sharp interference bands
    float bands = sin(t * 15.0);
    col *= 0.8 + 0.4 * smoothstep(-0.2, 0.2, bands);

    return col;
}

void main() {
    vec2 luv = acLayerNorm.xy;
    vec2 suv = acScreenNorm.xy;

    vec2 uv;
    vec2 aspect;
    if(followLayer) {
        uv = luv;
        aspect = vec2(acLayerSize.x / acLayerSize.y, 1.0);
    } else {
        uv = suv;
        aspect = vec2(acScreenSize.x / acScreenSize.y, 1.0);
    }

    vec2 p = (uv - 0.5) * aspect;

    vec4 source = texture2DCv(inputImg.texture, uv);

    // 2. Generate Distance Influence
    float dist = 0.0;
    const int SAMPLES = 16;

    for(int i = 0; i < SAMPLES; i++) {
        float sampleAngle = float(i) * (2.0 * PI / float(SAMPLES));
        vec2 sampleDir = vec2(cos(sampleAngle), sin(sampleAngle));

        // Sampling offset corrected by aspect to keep it circular
        vec2 offset = sampleDir * glowWidth * 0.1;
        offset.x /= aspect.x;

        vec2 sampleUV = uv + offset;
        float sampleLuma = getLuma(texture2DCv(inputImg.texture, sampleUV).rgb);

        dist += smoothstep(threshold, 1.0, sampleLuma);
    }
    dist /= float(SAMPLES);

    // 3. Twist & Phase Calculation
    float angle = atan(p.y, p.x);
    float timePhase = acTime * phaseSpeed;
    float auraMap = dist * frequency + (angle / PI) * twist + timePhase;

    // 4. Color Generation
    const vec3 phaseRGB = vec3(0.2, 0.1, 0.0);
    vec3 auraCol = vec3(
        auraPalette(auraMap + phaseRGB.r).r,
        auraPalette(auraMap + phaseRGB.g).g,
        auraPalette(auraMap + phaseRGB.b).b
    );

    // Fade aura based on distance
    float mask = smoothstep(0.0, 0.5, dist) * (1.0 - smoothstep(0.5, 1.2, dist));
    auraCol *= mask * brightness;

    // 5. Composite (Screen Blend)
    vec3 result = 1.0 - (1.0 - source.rgb) * (1.0 - auraCol);

    // Keep text interior bright
    if(getLuma(source.rgb) > 0.8) result = source.rgb;

    vec4 finalColor = vec4(result, source.a);

    // Mixing based on blend parameter
    gl_FragColor = mix(source, finalColor, blend);
}
